struct APIClient {
    let baseURL = URL(string: "https://api.example.com")!
    let decoder = JSONDecoder()

    func fetch<T: Decodable>(_ path: String) async throws -> T {
        let url = baseURL.appendingPathComponent(path)
        let (data, response) = try await URLSession.shared.data(from: url)

        guard let http = response as? HTTPURLResponse,
              (200...299).contains(http.statusCode) else {
            throw APIError.badResponse
        }

        return try decoder.decode(T.self, from: data)
    }
}

// Usage
let client = APIClient()
let users: [User] = try await client.fetch("/users")

struct User: Codable {
    let id: Int
    let fullName: String
    let email: String
    let createdAt: Date?

    enum CodingKeys: String, CodingKey {
        case id
        case fullName = "full_name"
        case email
        case createdAt = "created_at"
    }
}

// Or use decoder strategies instead of CodingKeys
let decoder = JSONDecoder()
decoder.keyDecodingStrategy = .convertFromSnakeCase
decoder.dateDecodingStrategy = .iso8601

let jsonStr = #"{"id": 1, "full_name": "Alice", "email": "a@b.com"}"#
let json = jsonStr.data(using: .utf8)!

let user = try decoder.decode(User.self, from: json)

protocol Endpoint {
    associatedtype Response: Decodable
    var path: String { get }
    var method: String { get }
    var headers: [String: String] { get }
}

struct NetworkClient {
    let baseURL: URL
    let session: URLSession
    var authToken: String?

    func request<E: Endpoint>(_ endpoint: E) async throws -> E.Response {
        var urlRequest = URLRequest(
            url: baseURL.appendingPathComponent(endpoint.path)
        )
        urlRequest.httpMethod = endpoint.method

        // Interceptor: add auth
        if let token = authToken {
            urlRequest.setValue("Bearer \(token)",
                               forHTTPHeaderField: "Authorization")
        }

        // Add endpoint-specific headers
        for (key, val) in endpoint.headers {
            urlRequest.setValue(val, forHTTPHeaderField: key)
        }

        let (data, _) = try await session.data(for: urlRequest)
        return try JSONDecoder().decode(E.Response.self, from: data)
    }
}
